/**
 * Calculate the next invoice number for a given year.
 * Format: INV-<year>-<counter> where counter is 4 digits, zero-padded.
 * @param {Array<string>} existingNumbers - Array of invoice numbers already used
 * @param {string} issueDate - Issue date in YYYY-MM-DD format
 * @returns {string} The next invoice number
 */
export function nextInvoiceNumber(existingNumbers, issueDate) {
  const year = issueDate.slice(0, 4);
  const prefix = `INV-${year}-`;

  const countersThisYear = existingNumbers
    .filter((num) => num.startsWith(prefix))
    .map((num) => {
      const counter = num.slice(prefix.length);
      return parseInt(counter, 10);
    })
    .filter((num) => !Number.isNaN(num));

  const maxCounter = countersThisYear.length > 0 ? Math.max(...countersThisYear) : 0;
  const nextCounter = maxCounter + 1;

  return `${prefix}${String(nextCounter).padStart(4, '0')}`;
}

